import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.DHtetOlu.js";const m=JSON.parse('{"title":"Files, import and export","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/files.md","filePath":"en/guide/files.md"}'),s={name:"en/guide/files.md"};function i(n,t,d,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="files-import-and-export" tabindex="-1">Files, import and export <a class="header-anchor" href="#files-import-and-export" aria-label="Permalink to &quot;Files, import and export&quot;">​</a></h1><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p>A project is a <strong><code>.magfem</code></strong> file (JSON) with the drawing, variables, materials, mesh, physics and views. Results are recomputed on opening.</p><ul><li><strong>New</strong>, <strong>Open</strong>, <strong>Save</strong> and <strong>Save as</strong> are on the top bar.</li><li>In Chrome and Edge, <strong>Save</strong> writes back to the same file, like an installed program; <strong>Save as</strong> picks another one. In Firefox and Safari, saving triggers a download.</li><li>Nothing leaves your machine: there is no server, account or cloud.</li></ul><h2 id="draft-and-automatic-copies" tabindex="-1">Draft and automatic copies <a class="header-anchor" href="#draft-and-automatic-copies" aria-label="Permalink to &quot;Draft and automatic copies&quot;">​</a></h2><p>The open project is kept in the browser (draft) on every change: closing the tab without saving does not lose the work. Also, after every minute of editing the previous version becomes an <strong>automatic copy</strong> (up to 10). If the project opens empty, a banner offers to recover the latest copy; the full list is under <strong>Automatic copies</strong>. Recovering can be undone.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The draft lives in the browser storage. Clearing the site data deletes the draft and the copies. Save important projects to a file.</p></div><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><p><strong>Import</strong> accepts:</p><table tabindex="0"><thead><tr><th>Format</th><th>What comes in</th></tr></thead><tbody><tr><td>DXF</td><td>lines, arcs, circles and polylines; coincident points are merged so regions close</td></tr><tr><td>SVG</td><td>paths (with arcs) converted to lines and arcs</td></tr><tr><td>FEMM (<code>.fem</code>)</td><td>geometry, materials, boundaries, circuits and block labels. Unlabeled regions stay out of the mesh, and edges without a property stay Neumann, as in FEMM</td></tr></tbody></table><p>FEMM materials are also available under <strong>Materials › Import from FEMM…</strong> (reads <code>matlib.dat</code>) and in the material list search.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>The <strong>Export</strong> button (top bar) exports what is in the active tab:</p><table tabindex="0"><thead><tr><th>Active tab</th><th>Formats</th></tr></thead><tbody><tr><td>Drawing</td><td>SVG (vector, in mm), DXF (LibreCAD, FreeCAD…), PNG, JPG</td></tr><tr><td>Field view</td><td>PNG, JPG</td></tr><tr><td>Plot</td><td>SVG, PNG, JPG, CSV</td></tr><tr><td>Table</td><td>CSV</td></tr></tbody></table><p>Also:</p><table tabindex="0"><thead><tr><th>What</th><th>Where</th></tr></thead><tbody><tr><td>Animation (WebM)</td><td>view bar, in transient and AC</td></tr><tr><td>Model as code</td><td><code>&lt;/&gt;</code> button next to <strong>Model</strong>: console script that rebuilds the project</td></tr></tbody></table><p>The exported script rebuilds the model exactly, with the same ids. It is the basis for <a href="./../scripting/console.html">automation</a>.</p>',17)])])}const g=e(s,[["render",i]]);export{m as __pageData,g as default};
